WITH filtered AS (SELECT *, CAST(pressure AS INT) AS pressure_int FROM device_readings WHERE device_code IN ('DV-01', 'DV-03', 'DV-04')) SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, pressure_int, MAX(pressure_int) OVER (PARTITION BY device_code) AS device_code_max_pressure_int, AVG(pressure_int) OVER (ORDER BY status_bits, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS pressure_int_avg_5 FROM filtered
